class Solution {
    public int[] findColumnWidth(int[][] grid){
        int[] answer=new int[grid[0].length];
        for(int[] row:grid)for(int col=0;col<row.length;col++)answer[col]=Math.max(answer[col],String.valueOf(row[col]).length());
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findColumnWidth(grid:Array<IntArray>):IntArray{
        val answer=IntArray(grid[0].size);
        for(row in grid)for(col in row.indices)answer[col]=maxOf(answer[col],row[col].toString().length);
        return answer
    }
}

